content.query:
let baseline = LoadTestSummary_CL | where run_id == '{Baseline}' | summarize arg_max(TimeGenerated, *);
let candidate = LoadTestSummary_CL | where run_id == '{Candidate}' | summarize arg_max(TimeGenerated, *);
let rows = (b:(*), c:(*)) {
    union
        (b | project Metric='Plan CPU max %',      Baseline=plan_CpuPercentage_max,            Candidate=toscalar(c | project plan_CpuPercentage_max)),
        (b | project Metric='Plan Memory max %',   Baseline=plan_MemoryPercentage_max,         Candidate=toscalar(c | project plan_MemoryPercentage_max)),
        (b | project Metric='SQL DTU max %',       Baseline=sql_dtu_consumption_percent_max,   Candidate=toscalar(c | project sql_dtu_consumption_percent_max)),
        (b | project Metric='SQL CPU max %',       Baseline=sql_cpu_percent_max,               Candidate=toscalar(c | project sql_cpu_percent_max)),
        (b | project Metric='SQL Log-write max %', Baseline=sql_log_write_percent_max,         Candidate=toscalar(c | project sql_log_write_percent_max)),
        (b | project Metric='App 5xx max',         Baseline=app_Http5xx_max,                   Candidate=toscalar(c | project app_Http5xx_max))
};
rows(baseline, candidate)
| extend Delta = iif(Baseline == 0 or isnull(Baseline) or isnull(Candidate), real(null), (Candidate - Baseline) / Baseline)
